{
  "predictors": [
    {
      "name": "Earnings Growth Consistency",
      "construction": "Calculate the standard deviation of quarterly earnings growth rates over the past 5 years using Compustat data.",
      "rationale": "Firms with more consistent earnings growth may be perceived as less risky, potentially leading to higher future returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "R&D Intensity Change",
      "construction": "Compute the year-over-year percentage change in R&D expenditure divided by total assets using Compustat data.",
      "rationale": "An increase in R&D intensity may signal future growth opportunities and innovation potential.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Trading Volume",
      "construction": "Aggregate the total volume of insider purchases minus sales over the past year using SEC Form 4 filings.",
      "rationale": "High insider buying relative to selling may indicate management's confidence in the firm's future prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration Risk",
      "construction": "Calculate the percentage of total sales attributed to the top 5 customers from annual reports.",
      "rationale": "Firms with lower customer concentration may have more stable revenue streams and less risk.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Environmental Compliance Score",
      "construction": "Develop a score based on the number of environmental violations reported in the past year using EPA data.",
      "rationale": "Firms with fewer environmental issues may face lower regulatory risks and potential fines.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Count the number of citations received by the firm's patents over the past 3 years using USPTO data.",
      "rationale": "Highly cited patents may indicate valuable innovations that can drive future profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Create an index based on employee reviews and satisfaction scores from sources like Glassdoor.",
      "rationale": "Higher employee satisfaction can lead to better productivity and lower turnover, enhancing firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Diversification",
      "construction": "Measure the number of distinct suppliers a firm uses, as reported in annual filings.",
      "rationale": "Firms with more diversified supply chains may be less vulnerable to disruptions.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Sentiment",
      "construction": "Analyze the sentiment of social media mentions over the past year using natural language processing techniques.",
      "rationale": "Positive sentiment may reflect favorable public perception and potential consumer demand.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Calculate the proportion of board members from diverse backgrounds using proxy statements.",
      "rationale": "Diverse boards may offer a wider range of perspectives, potentially leading to better decision-making.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
